import { useQuery } from "@tanstack/react-query";
import { QueryConfig } from "@/api/api";
import { ReleaseNoteEntry, ReleaseNotesManifest } from "@/types/release-notes";

export const RELEASE_NOTES_QUERY_KEY = "release-notes";

/**
 * The manifest is a static asset shipped inside the image (generated by
 * `scripts/release-notes/generate-manifest.mjs`), not an API call and not a request to
 * comet.com — that is what lets the panel work in an air-gapped install.
 *
 * It is fetched directly rather than through the `api` axios instance because it is served by
 * the frontend itself, not by the backend under `/api`.
 */
const RELEASE_NOTES_URL = `${
  import.meta.env.BASE_URL ?? "/"
}release-notes.json`.replace(/\/{2,}/g, "/");

const getReleaseNotes = async ({
  signal,
}: {
  signal?: AbortSignal;
}): Promise<ReleaseNoteEntry[]> => {
  const response = await fetch(RELEASE_NOTES_URL, { signal });

  if (!response.ok) {
    throw new Error(`Failed to load release notes: ${response.status}`);
  }

  const manifest = (await response.json()) as ReleaseNotesManifest;

  return manifest.entries ?? [];
};

export default function useReleaseNotes(
  options?: QueryConfig<ReleaseNoteEntry[]>,
) {
  return useQuery({
    queryKey: [RELEASE_NOTES_QUERY_KEY, {}],
    queryFn: ({ signal }) => getReleaseNotes({ signal }),
    // Immutable for the lifetime of the deployed build.
    staleTime: Infinity,
    ...options,
  });
}
